// Regenerates lib/isoShellAssets.ts from the gold-standard public/models/microwave.html.
// The generated file is the shared "shell" (CSS, SVG defs, audio dock, isometric kernel, narration runtime)
// that Qwen-generated lessons are assembled into, so every new device inherits the exact gold-standard craft.
// Usage: node scripts/build-iso-assets.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const src = readFileSync(resolve(root, 'public/models/microwave.html'), 'utf8').split(/\r?\n/);

// 1-based inclusive slice helper
const slice = (from, to) => src.slice(from - 1, to).join('\n');

const css = slice(8, 445);
const defs = slice(465, 504);

let dock = slice(523, 560);
dock = dock.replace(
  /(<div class="subtitle-pill" id="subtitleBox" aria-live="polite">)[\s\S]*?(<\/div>)/,
  '$1$2'
);

let kernel = slice(570, 692);
kernel = kernel
  .replace('const SCALE = 2.05;', 'let SCALE = 2.05;')
  .replace('const OX = 355;', 'let OX = 355;')
  .replace('const OY = 206;', 'let OY = 206;');

const sinStart = src.findIndex((l) => l.includes('function buildSinusoidal3DWave'));
let sinEnd = sinStart;
while (!/^ {6}\}\s*$/.test(src[sinEnd])) sinEnd++;
const sinus = src.slice(sinStart, sinEnd + 1).join('\n');

const runtimeA = slice(1267, 1380);

const esc = (s) => s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');

const out = `// AUTO-GENERATED by scripts/build-iso-assets.mjs from public/models/microwave.html — do not edit by hand.
export const ISO_SHELL_CSS = \`${esc(css)}\`;

export const ISO_SHELL_DEFS = \`${esc(defs)}\`;

export const ISO_SHELL_DOCK = \`${esc(dock)}\`;

export const ISO_KERNEL_JS = \`${esc(kernel)}

${esc(sinus)}\`;

export const ISO_RUNTIME_A_JS = \`${esc(runtimeA)}\`;
`;

writeFileSync(resolve(root, 'lib/isoShellAssets.ts'), out, 'utf8');
console.log('lib/isoShellAssets.ts written:', out.length, 'chars');
